// Port sederhana dari skills/kopi-sumatra-content/scripts/generate_batch.py
// Rotasi Pilar x Format x Kategori-Footage x Narator berbasis tanggal. Lengkapi bank fakta/
// kata kunci footage sesuai referensi di repo sebelum dipakai produksi - ini hanya kerangka.
const PILLARS = ['asal_usul','penanaman','panen','giling_basah','sortasi_fermentasi','roasting','brewing','cita_rasa','budaya','mitos_fakta'];
const FORMATS = ['hook_fakta_cepat','pov_kunjungan','day_in_life','tutorial_mini','mitos_vs_fakta','versus','asmr_proses','sejarah_singkat','tanya_jawab','behind_the_scenes'];
const FOOTAGE_CATEGORIES = ['kebun_dataran_tinggi','giling_roastery','warung_brewing'];
const NARRATORS = ['bahri','nur','adit'];

function combos() {
  const out = [];
  for (const p of PILLARS) for (const f of FORMATS) for (const k of FOOTAGE_CATEGORIES) for (const n of NARRATORS) out.push([p, f, k, n]);
  return out;
}

// simple deterministic shuffle (mulberry32) seeded by string
function seededShuffle(arr, seedStr) {
  let seed = 0;
  for (let i = 0; i < seedStr.length; i++) seed = (seed * 31 + seedStr.charCodeAt(i)) >>> 0;
  const rand = () => {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

const dateStr = $today.toFormat('yyyy-MM-dd');
const dayOrdinal = Math.floor(new Date(dateStr).getTime() / 86400000);
const count = 100;
const all = combos();
const n = all.length;
const passNumber = Math.floor((dayOrdinal * count) / n);
const order = seededShuffle(all, `kopi-sumatra-pass-${passNumber}`);
const start = (dayOrdinal * count) % n;
let window_ = [];
if (start + count <= n) window_ = order.slice(start, start + count);
else window_ = order.slice(start).concat(order.slice(0, start + count - n));

return window_.map(([pilar, format, kategoriFootage, narator], i) => ({
  json: { index: i + 1, date: dateStr, pilar, format, kategoriFootage, narator }
}));
